 69→func TestRunClean_NoOrphanedItems(t *testing.T) {
 70→	setupCleanTestRepo(t)
 71→
 72→	var stdout bytes.Buffer
 73→	err := runClean(context.Background(), &stdout, false)
 74→	if err != nil {
 75→		t.Fatalf("runClean() error = %v", err)
 76→	}
 77→
 78→	output := stdout.String()
 79→	if !strings.Contains(output, "No orphaned items") {
 80→		t.Errorf("Expected 'No orphaned items' message, got: %s", output)
 81→	}
 82→}
