 19→// Reset deletes the shadow branch and session state for the current HEAD.
 20→// This allows starting fresh without existing checkpoints.
 21→func (s *ManualCommitStrategy) Reset(ctx context.Context) error {
 22→	repo, err := OpenRepository(ctx)
 23→	if err != nil {
 24→		return fmt.Errorf("failed to open git repository: %w", err)
 25→	}
 26→
 27→	// Get current HEAD
 28→	head, err := repo.Head()
 29→	if err != nil {
 30→		return fmt.Errorf("failed to get HEAD: %w", err)
 31→	}
 32→
 33→	// Get current worktree ID for shadow branch naming
 34→	worktreePath, err := paths.WorktreeRoot(ctx)
 35→	if err != nil {
 36→		return fmt.Errorf("failed to get worktree path: %w", err)
 37→	}
 38→	worktreeID, err := paths.GetWorktreeID(worktreePath)
 39→	if err != nil {
 40→		return fmt.Errorf("failed to get worktree ID: %w", err)
 41→	}
 42→
 43→	// Get shadow branch name for current HEAD
 44→	shadowBranchName := getShadowBranchNameForCommit(head.Hash().String(), worktreeID)
 45→
 46→	// Check if shadow branch exists
 47→	refName := plumbing.NewBranchReferenceName(shadowBranchName)
 48→	_, err = repo.Reference(refName, true)
 49→	hasShadowBranch := err == nil
 50→
 51→	// Find sessions for this commit
 52→	sessions, err := s.findSessionsForCommit(ctx, head.Hash().String())
 53→	if err != nil {
 54→		sessions = nil // Ignore error, treat as no sessions
 55→	}
 56→
 57→	// If nothing to reset, return early
 58→	if !hasShadowBranch && len(sessions) == 0 {
 59→		fmt.Fprintf(os.Stderr, "Nothing to reset for %s\n", shadowBranchName)
 60→		return nil
 61→	}
 62→
 63→	// Clear all sessions for this commit
 64→	clearedSessions := make([]string, 0)
 65→	for _, state := range sessions {
 66→		if err := s.clearSessionState(ctx, state.SessionID); err != nil {
 67→			fmt.Fprintf(os.Stderr, "Warning: failed to clear session state for %s: %v\n", state.SessionID, err)
 68→		} else {
 69→			clearedSessions = append(clearedSessions, state.SessionID)
 70→		}
 71→	}
 72→
 73→	// Report cleared session states with session IDs
 74→	if len(clearedSessions) > 0 {
 75→		for _, sessionID := range clearedSessions {
 76→			fmt.Fprintf(os.Stderr, "Cleared session state for %s\n", sessionID)
 77→		}
 78→	}
 79→
 80→	// Delete the shadow branch if it exists
 81→	if hasShadowBranch {
 82→		if err := DeleteBranchCLI(ctx, shadowBranchName); err != nil {
 83→			return fmt.Errorf("failed to delete shadow branch: %w", err)
 84→		}
 85→		fmt.Fprintf(os.Stderr, "Deleted shadow branch %s\n", shadowBranchName)
 86→	}
 87→
 88→	return nil
 89→}
 90→
 91→// ResetSession clears a single session's state and removes the shadow branch
 92→// if no other sessions reference it. File changes remain in the working directory.
 93→func (s *ManualCommitStrategy) ResetSession(ctx context.Context, sessionID string) error {
 94→	// Load the session state
 95→	state, err := s.loadSessionState(ctx, sessionID)
 96→	if err != nil {
 97→		return fmt.Errorf("failed to load session state: %w", err)
 98→	}
 99→	if state == nil {
100→		return fmt.Errorf("session not found: %s", sessionID)
101→	}
102→
103→	// Clear the session state file
104→	if err := s.clearSessionState(ctx, sessionID); err != nil {
105→		return fmt.Errorf("failed to clear session state: %w", err)
106→	}
107→	fmt.Fprintf(os.Stderr, "Cleared session state for %s\n", sessionID)
108→
109→	// Determine the shadow branch for this session
110→	shadowBranchName := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
111→
112→	// Open repository
113→	repo, err := OpenRepository(ctx)
114→	if err != nil {
115→		return fmt.Errorf("failed to open repository: %w", err)
116→	}
117→
118→	// Clean up shadow branch if no other sessions need it
119→	if err := s.cleanupShadowBranchIfUnused(ctx, repo, shadowBranchName, sessionID); err != nil {
120→		fmt.Fprintf(os.Stderr, "Warning: failed to clean up shadow branch %s: %v\n", shadowBranchName, err)
121→	} else {
122→		// Check if it was actually deleted via git CLI (go-git's cache
123→		// may be stale after CLI-based deletion with packed refs)
124→		if err := branchExistsCLI(ctx, shadowBranchName); err != nil {
125→			fmt.Fprintf(os.Stderr, "Deleted shadow branch %s\n", shadowBranchName)
126→		}
127→	}
128→
129→	return nil
130→}
